import React from 'react';
import config from '../../config/site-config';

interface Props {
  title: string;
}

export function Head({ title = config.siteTitle }: Props) {
  return (
    <>
      <title>{title}</title>
    </>
  );
}

// Keep the old component for backward compatibility
const PageTitle = (props: Props) => {
  const { title = config.siteTitle } = props;

  return <div style={{ display: 'none' }}>{title}</div>;
};

export default PageTitle;
